/* ui/eq.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function eqResponseAt(freq, cfg) {
    const f = P.clamp(freq, P.EQ_MIN_FREQ, P.EQ_MAX_FREQ);
    const f0 = P.clamp(cfg.freq, P.EQ_MIN_FREQ, P.EQ_MAX_FREQ);
    const Q = P.clamp(cfg.q || 1, P.EQ_MIN_Q, P.EQ_MAX_Q);
    const gain = P.clamp(cfg.gain || 0, P.EQ_MIN_GAIN, P.EQ_MAX_GAIN);
    const w0 = f / f0;
    switch (cfg.type) {
      case "lowshelf": {
        const g = Math.pow(10, gain / 40);
        const x = Math.log2(Math.max(w0, 0.001));
        const k = 1 / (1 + Math.exp(x * 4));
        return 20 * Math.log10(1 + (g - 1) * k);
      }
      case "highshelf": {
        const g = Math.pow(10, gain / 40);
        const x = Math.log2(Math.max(w0, 0.001));
        const k = 1 / (1 + Math.exp(-x * 4));
        return 20 * Math.log10(1 + (g - 1) * k);
      }
      case "lowpass": {
        const d = Math.pow(w0, 2) - 1;
        const b = w0 / Q;
        return 20 * Math.log10(1 / Math.sqrt(d * d + b * b));
      }
      case "highpass": {
        const d = 1 - Math.pow(w0, 2);
        const b = w0 / Q;
        return 20 * Math.log10((w0 * w0) / Math.sqrt(d * d + b * b));
      }
      case "notch": {
        const d = 1 - Math.pow(w0, 2);
        const b = w0 / Q;
        return 20 * Math.log10(Math.abs(d) / Math.sqrt(d * d + b * b));
      }
      default: { // peaking
        const A = Math.pow(10, gain / 40);
        const d = 1 - Math.pow(w0, 2);
        const b = w0 / Q;
        const num = Math.sqrt(Math.pow(d, 2) + Math.pow(A * b, 2));
        const den = Math.sqrt(Math.pow(d, 2) + Math.pow(b / A, 2));
        return 20 * Math.log10(num / den);
      }
    }
  }

  function eqCanvasMetrics(canvas) {
    const w = canvas.width, h = canvas.height;
    const padX = 28, padY = 14;
    const innerW = w - padX * 2, innerH = h - padY * 2;
    const dbToY = (db) => padY + innerH * (1 - (db - P.EQ_MIN_GAIN) / (P.EQ_MAX_GAIN - P.EQ_MIN_GAIN));
    const yToDb = (y) => P.EQ_MIN_GAIN + (1 - (P.clamp(y, padY, h - padY) - padY) / innerH) * (P.EQ_MAX_GAIN - P.EQ_MIN_GAIN);
    const freqToX = (f) => padX + innerW * (Math.log10(P.clamp(f, P.EQ_MIN_FREQ, P.EQ_MAX_FREQ) / P.EQ_MIN_FREQ) / Math.log10(P.EQ_MAX_FREQ / P.EQ_MIN_FREQ));
    const xToFreq = (x) => P.EQ_MIN_FREQ * Math.pow(P.EQ_MAX_FREQ / P.EQ_MIN_FREQ, P.clamp(x - padX, 0, innerW) / innerW);
    return { w, h, padX, padY, innerW, innerH, dbToY, yToDb, freqToX, xToFreq };
  }

  function drawEqCurve() {
    document.querySelectorAll("#playerEqCanvas").forEach((canvas) => {
      if (!(canvas instanceof HTMLCanvasElement)) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      const m = P.eqCanvasMetrics(canvas);
      const { w, h, padX, padY, dbToY, freqToX } = m;
      ctx.clearRect(0, 0, w, h);
      const bg = P.cssVar("--bg-elevated-2") || "#141414";
      const border = P.cssVar("--border") || "#2a2a2a";
      const text = P.cssVar("--text") || "#ffffff";
      const muted = P.cssVar("--muted") || "#a3a3a3";
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);

      ctx.strokeStyle = border;
      ctx.lineWidth = 1;
      [-36, -24, -12, 0, 12, 24, 36].forEach((db) => {
        const y = dbToY(db);
        ctx.beginPath(); ctx.moveTo(padX, y); ctx.lineTo(w - padX, y); ctx.stroke();
      });
      [31, 62, 125, 250, 500, 1000, 2000, 4000, 8000, 16000].forEach((f) => {
        const x = freqToX(f);
        ctx.beginPath(); ctx.moveTo(x, padY); ctx.lineTo(x, h - padY); ctx.stroke();
      });
      ctx.fillStyle = muted;
      ctx.font = "10px system-ui, sans-serif";
      ctx.textAlign = "right";
      [36, 24, 12, 0, -12, -24, -36].forEach((db) => ctx.fillText(`${db}`, padX - 4, dbToY(db) + 3));

      const filters = (P.state.eqFilters || []).filter((f) => f && f.enabled);
      const points = [];
      for (let i = 0; i <= m.innerW; i++) {
        const f = P.EQ_MIN_FREQ * Math.pow(P.EQ_MAX_FREQ / P.EQ_MIN_FREQ, i / m.innerW);
        let db = 0;
        for (const cfg of filters) db += P.eqResponseAt(f, cfg);
        db = P.clamp(db, P.EQ_MIN_GAIN - 6, P.EQ_MAX_GAIN + 6);
        points.push({ x: padX + i, y: dbToY(db) });
      }

      ctx.beginPath();
      points.forEach((p, i) => { if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y); });
      ctx.strokeStyle = P.state.eqEnabled ? text : muted;
      ctx.lineWidth = 2;
      ctx.stroke();
      const zeroY = dbToY(0);
      ctx.lineTo(w - padX, zeroY); ctx.lineTo(padX, zeroY); ctx.closePath();
      ctx.fillStyle = P.state.eqEnabled ? "rgba(255,255,255,0.08)" : "rgba(163,163,163,0.06)";
      ctx.fill();

      (P.state.eqFilters || []).forEach((cfg, index) => {
        let db = 0;
        for (const c of filters) db += P.eqResponseAt(cfg.freq, c);
        const x = freqToX(cfg.freq);
        const y = dbToY(P.clamp(db, P.EQ_MIN_GAIN - 6, P.EQ_MAX_GAIN + 6));
        ctx.beginPath();
        ctx.arc(x, y, P.eqDrag.index === index ? 6 : 4.5, 0, Math.PI * 2);
        ctx.fillStyle = !P.state.eqEnabled || !cfg.enabled ? muted : text;
        ctx.fill();
        ctx.strokeStyle = bg;
        ctx.lineWidth = 1.5;
        ctx.stroke();
      });
    });
  }
  function eqCanvasPoint(canvas, ev) {
    const rect = canvas.getBoundingClientRect();
    const x = ((ev.clientX - rect.left) / rect.width) * canvas.width;
    const y = ((ev.clientY - rect.top) / rect.height) * canvas.height;
    return { x, y };
  }
  function eqHitTest(canvas, ev) {
    const p = P.eqCanvasPoint(canvas, ev);
    const m = P.eqCanvasMetrics(canvas);
    let best = -1, bestDist = Infinity;
    (P.state.eqFilters || []).forEach((cfg, index) => {
      const filters = (P.state.eqFilters || []).filter((f) => f && f.enabled);
      let db = 0;
      for (const c of filters) db += P.eqResponseAt(cfg.freq, c);
      const x = m.freqToX(cfg.freq);
      const y = m.dbToY(P.clamp(db, P.EQ_MIN_GAIN - 6, P.EQ_MAX_GAIN + 6));
      const dist = Math.hypot(p.x - x, p.y - y);
      if (dist < 14 && dist < bestDist) { best = index; bestDist = dist; }
    });
    return best;
  }
  function applyEqCanvasDrag(canvas, ev) {
    if (P.eqDrag.index < 0) return;
    const cfg = P.state.eqFilters[P.eqDrag.index];
    if (!cfg) return;
    const p = P.eqCanvasPoint(canvas, ev);
    const m = P.eqCanvasMetrics(canvas);
    const freq = P.clamp(Math.round(m.xToFreq(p.x)), P.EQ_MIN_FREQ, P.EQ_MAX_FREQ);
    const gain = P.clamp(Math.round(m.yToDb(p.y)), P.EQ_MIN_GAIN, P.EQ_MAX_GAIN);
    cfg.freq = freq;
    if (cfg.type !== "lowpass" && cfg.type !== "highpass" && cfg.type !== "notch") cfg.gain = gain;
    P.state.eqFilters[P.eqDrag.index] = P.normalizeEqFilter(cfg, P.eqDrag.index);
    if (P.state.eqEnabled) P.ensureEqChain();
    P.applyEqState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function bindEqCanvasInteractions() {
    document.querySelectorAll("#playerEqCanvas").forEach((canvas) => {
      if (!(canvas instanceof HTMLCanvasElement) || canvas.dataset.eqBound === "1") return;
      canvas.dataset.eqBound = "1";
      canvas.style.touchAction = "none";
      canvas.addEventListener("pointerdown", (ev) => {
        if (!P.state.eqEnabled) return;
        const idx = P.eqHitTest(canvas, ev);
        if (idx < 0) return;
        P.eqDrag.index = idx; P.eqDrag.pointerId = ev.pointerId;
        canvas.setPointerCapture?.(ev.pointerId);
        P.applyEqCanvasDrag(canvas, ev);
      });
      canvas.addEventListener("pointermove", (ev) => {
        if (P.eqDrag.pointerId !== ev.pointerId || P.eqDrag.index < 0) return;
        P.applyEqCanvasDrag(canvas, ev);
      });
      const end = (ev) => {
        if (P.eqDrag.pointerId !== ev.pointerId) return;
        P.eqDrag.index = -1; P.eqDrag.pointerId = null;
        P.drawEqCurve();
      };
      canvas.addEventListener("pointerup", end);
      canvas.addEventListener("pointercancel", end);
    });
  }

  function renderEqFilters() {
    document.querySelectorAll("#playerEqFilters").forEach((container) => {
      container.replaceChildren();
      P.state.eqFilters.forEach((cfg, index) => {
        const row = document.createElement("div");
        row.className = "eq-filter";
        row.dataset.eqIndex = String(index);
        row.innerHTML = `
          <div class="eq-filter-head">
            <label class="eq-toggle"><input type="checkbox" data-eq-field="enabled" ${cfg.enabled ? "checked" : ""}><span>${cfg.type} #${index + 1}</span></label>
            <button type="button" class="player-queue-text-btn" data-eq-remove="${index}">${P.pt("eqRemove")}</button>
          </div>
          <div class="eq-filter-grid">
            <label class="eq-field"><span>${P.pt("eqType")}</span>
              <select class="settings-select" data-eq-field="type">
                ${["peaking","lowshelf","highshelf","lowpass","highpass","notch"].map((t) => `<option value="${t}" ${cfg.type===t?"selected":""}>${t}</option>`).join("")}
              </select>
            </label>
            <label class="eq-field"><span>${P.pt("eqFreq")}</span><input class="settings-select" type="number" min="${P.EQ_MIN_FREQ}" max="${P.EQ_MAX_FREQ}" step="1" value="${cfg.freq}" data-eq-field="freq"></label>
            <label class="eq-field"><span>${P.pt("eqGain")}</span><input class="settings-select" type="number" min="${P.EQ_MIN_GAIN}" max="${P.EQ_MAX_GAIN}" step="1" value="${cfg.gain}" data-eq-field="gain"></label>
            <label class="eq-field"><span>${P.pt("eqQ")}</span><input class="settings-select" type="number" min="${P.EQ_MIN_Q}" max="${P.EQ_MAX_Q}" step="0.1" value="${cfg.q}" data-eq-field="q"></label>
          </div>`;
        container.appendChild(row);
      });
    });
  }

  function syncEqVisual() {
    P.renderEqFilters();
    P.bindEqCanvasInteractions();
    P.drawEqCurve();
    document.querySelectorAll("[data-eq-setting]").forEach((root) => {
      root.classList.toggle("is-disabled", !P.state.eqEnabled);
      root.querySelectorAll("input,select,button").forEach((el) => {
        if (el.id === "playerEqAdd" || el.id === "playerEqReset" || el.closest(".eq-toggle")) return;
        if (el.dataset.playerSetting === "eqEnabled") return;
        el.disabled = !P.state.eqEnabled;
      });
    });
  }
  Object.assign(P, { eqResponseAt, eqCanvasMetrics, drawEqCurve, eqCanvasPoint, eqHitTest, applyEqCanvasDrag, bindEqCanvasInteractions, renderEqFilters, syncEqVisual });
}
